package com.bank.consistency;

import java.math.BigDecimal;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Logger;

public class AcidBaseDemo {
    private static final Logger log = Logger.getLogger(AcidBaseDemo.class.getName());

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        TransferService service = new TransferService(repo);

        // ACID path: all-or-nothing transfer.
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));

        // ACID path: fails and rolls back (amount too large).
        try {
            service.transfer("CUR3001", "SAV2001", new BigDecimal("9999999"));
        } catch (RuntimeException e) {
            log.severe("Transfer rolled back: " + e.getMessage());
        }

        // BASE path: eventual-consistency view counter, never blocks.
        ViewCounter counter = new ViewCounter();
        for (int i = 0; i < 5; i++) counter.increment();
        log.info(() -> "Offer banner views (eventually consistent): " + counter.read());
    }
}

// ─── Would be Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }

    void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0)  // enforces the consistency rule
            throw new IllegalStateException("Insufficient balance in " + accountId);
        balance = balance.subtract(amount);
    }
    void credit(BigDecimal amount) { balance = balance.add(amount); }
}

// ─── Would be AccountRepository.java ───
class AccountRepository {
    private final java.util.Map<String, Account> store = new java.util.HashMap<>();
    AccountRepository() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }
    Account findById(String id) { return store.get(id); }
}

// ─── Would be TransferService.java ───
class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final AccountRepository repo;
    TransferService(AccountRepository repo) { this.repo = repo; }

    // ACID: this whole method is one atomic unit — debit+credit or neither.
    void transfer(String fromId, String toId, BigDecimal amount) {
        Account from = repo.findById(fromId);
        Account to = repo.findById(toId);
        BigDecimal fromBefore = from.getBalance();
        BigDecimal toBefore = to.getBalance();
        try {
            from.debit(amount);   // may throw → triggers rollback below
            to.credit(amount);
            log.info(() -> "COMMIT " + fromId + "→" + toId + " Rs." + amount);
        } catch (RuntimeException e) {
            // Atomicity: undo any partial change so state stays valid.
            restore(from, fromBefore);
            restore(to, toBefore);
            throw e;
        }
    }
    private void restore(Account a, BigDecimal before) {
        BigDecimal delta = before.subtract(a.getBalance());
        if (delta.signum() > 0) a.credit(delta); else a.debit(delta.negate());
    }
}

