// BASE: always available, soft state, eventually consistent.
class ViewCounter {
    private final AtomicLong views = new AtomicLong();
    void increment() { views.incrementAndGet(); }   // never blocks
    long read() { return views.get(); }              // may be briefly stale across nodes
}
